package bst

import (
	"reflect"
	"testing"
)

func TestInsertAndContains(t *testing.T) {
	t2 := New()
	t2.Insert(5)
	t2.Insert(3)
	t2.Insert(7)
	if !t2.Contains(5) || !t2.Contains(3) || !t2.Contains(7) {
		t.Fatal("should contain inserted keys")
	}
	if t2.Contains(99) {
		t.Fatal("should not contain 99")
	}
}

func TestInOrderSorted(t *testing.T) {
	t2 := New()
	for _, v := range []int{5, 3, 7, 1, 4, 6, 8} {
		t2.Insert(v)
	}
	want := []int{1, 3, 4, 5, 6, 7, 8}
	if !reflect.DeepEqual(t2.InOrder(), want) {
		t.Fatalf("expected %v got %v", want, t2.InOrder())
	}
}

func TestMinMax(t *testing.T) {
	t2 := New()
	t2.Insert(10)
	t2.Insert(2)
	t2.Insert(15)
	t2.Insert(7)
	min, ok := t2.Min()
	if !ok || min != 2 {
		t.Fatalf("expected min=2, got %d ok=%v", min, ok)
	}
	max, ok := t2.Max()
	if !ok || max != 15 {
		t.Fatalf("expected max=15, got %d ok=%v", max, ok)
	}
}

func TestEmptyTree(t *testing.T) {
	t2 := New()
	if t2.Contains(1) {
		t.Fatal("empty tree should contain nothing")
	}
	if got := t2.InOrder(); len(got) != 0 {
		t.Fatalf("expected empty slice, got %v", got)
	}
	_, ok := t2.Min()
	if ok {
		t.Fatal("expected ok=false on empty tree")
	}
}

func TestDuplicateInsert(t *testing.T) {
	t2 := New()
	t2.Insert(5)
	t2.Insert(5)
	if len(t2.InOrder()) != 1 {
		t.Fatal("duplicate insert should not add a second node")
	}
}
